<?php
declare(strict_types=1);
require __DIR__ . '/config.php'; require_login(); require __DIR__ . '/patient-layout.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$pdo=db();$q=$pdo->prepare('SELECT * FROM current_accounts WHERE id=?');$q->execute([$id]);$account=$q->fetch();if(!$account){http_response_code(404);exit('Cari kart bulunamadı.');}$rows=[];try{$q=$pdo->prepare('SELECT m.*,s.stock_code,s.stock_name FROM stock_movements m JOIN stock_cards s ON s.id=m.stock_id WHERE m.current_account_id=? ORDER BY m.movement_date DESC,m.id DESC');$q->execute([$id]);$rows=$q->fetchAll();}catch(Throwable $e){}patient_header('Cari Hareketleri','cash');
?><main class="patient-container cam-page"><section class="cam-card"><header><h1>Cari Hareketleri</h1><p><?=e($account['code'].' — '.$account['title'])?></p></header><div><table><thead><tr><th>TARİH</th><th>HAREKET</th><th>STOK KARTI</th><th>FATURA NO</th><th>MİKTAR</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e(format_date_tr($row['movement_date']))?></td><td><?=e($row['movement_type'])?></td><td><?=e($row['stock_code'].' — '.$row['stock_name'])?></td><td><?=e($row['invoice_no']?:'—')?></td><td><?=e((string)$row['quantity'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">Bu cariye ait hareket bulunmuyor.</td></tr><?php endif?></tbody></table></div></section></main><style>.cam-page{max-width:1180px!important;margin:auto;padding:28px 20px}.cam-card{background:#fff;border:1px solid #e1e2e8;border-radius:10px;overflow:hidden;box-shadow:0 3px 12px #1e283c0f}.cam-card header{padding:22px 24px;border-bottom:1px solid #e1e2e8}.cam-card h1{margin:0 0 5px;font-size:21px}.cam-card p{margin:0;color:#7b7b8d}.cam-card>div{overflow:auto}.cam-card table{width:100%;min-width:750px;border-collapse:collapse}.cam-card th,.cam-card td{padding:14px 18px;border-bottom:1px solid #e1e2e8;text-align:left}.cam-card th{font-size:12px;color:#6d6b7f}.empty{text-align:center;color:#7b7b8d}</style><?php patient_footer(); ?>
